    sources_schema_yml,
    models__stg_orders_sql,
    models__schema_yml,
    tests__assert_positive_amounts_sql,
)


class TestStgOrdersBasic:
    """Test basic staging model compilation and execution"""

    @pytest.fixture(scope="class")
    def seeds(self):
        return {
            "raw_orders.csv": seeds__raw_orders_csv,
        }

    @pytest.fixture(scope="class")
    def models(self):
        return {
            "sources.yml": sources_schema_yml,
            "stg_orders.sql": models__stg_orders_sql,
            "schema.yml": models__schema_yml,
        }

    @pytest.fixture(scope="class")
    def tests(self):
        return {
            "assert_positive_amounts.sql": tests__assert_positive_amounts_sql,
        }

    def test_model_compiles(self, project):
        """Verify that the staging model SQL compiles without errors"""
        # Run compile to verify model compiles
        results = run_dbt(["compile"])
        assert len(results) > 0

        # Check that stg_orders is in the manifest
        manifest = get_manifest(project.project_root)
        assert "model.test.stg_orders" in manifest.nodes

