        """Verify that the staging model can be executed"""
        # Load seed data
        results = run_dbt(["seed"])
        assert len(results) == 1

        # Run the staging model
        results = run_dbt(["run"])
        assert len(results) == 1

        # Verify the model was created
        created_objects = project.get_tables_in_schema()
        assert "stg_orders" in created_objects
        assert created_objects["stg_orders"] == "view"

