        """Verify schema.yml contains column-level test definitions"""
        manifest = get_manifest(project.project_root)

        # Check for unique test on id column
        unique_test_exists = any(
            "unique" in node_id and "stg_orders_id" in node_id
            for node_id in manifest.nodes.keys()
            if node_id.startswith("test.")
        )
        assert unique_test_exists, "unique test on id column should exist"

        # Check for not_null test on id column
        not_null_test_exists = any(
            "not_null" in node_id and "stg_orders_id" in node_id
            for node_id in manifest.nodes.keys()
            if node_id.startswith("test.")
        )
        assert not_null_test_exists, "not_null test on id column should exist"

    def test_custom_test_exists(self, project):
        """Verify custom test file exists with valid SQL"""
        manifest = get_manifest(project.project_root)

        # Check that custom test is in the manifest
        custom_test_exists = any(
            "assert_positive_amounts" in node_id
            for node_id in manifest.nodes.keys()
            if node_id.startswith("test.")
        )
        assert custom_test_exists, "assert_positive_amounts custom test should exist"

    def test_custom_test_validates_positive_amounts(self, project):
        """Verify custom test correctly identifies negative amounts"""
        # Load seed data
        run_dbt(["seed"])

        # Run the staging model
        run_dbt(["run"])

        # Run tests - should fail because we have a negative amount in the seed data
        results = run_dbt(["test"], expect_pass=False)

        # Find the assert_positive_amounts test result
        positive_test_result = None
        for result in results:
            if "assert_positive_amounts" in result.node.unique_id:
                positive_test_result = result
                break

        assert positive_test_result is not None, "assert_positive_amounts test should run"
        assert positive_test_result.status == "fail", (
            "assert_positive_amounts test should fail with negative amounts in data"
        )


class TestStgOrdersTransformations:
