    @pytest.fixture(scope="class")
    def seeds(self):
        return {
            "raw_orders.csv": seeds__raw_orders_csv,
        }

    @pytest.fixture(scope="class")
    def models(self):
        return {
            "sources.yml": sources_schema_yml,
            "stg_orders.sql": models__stg_orders_sql,
            "schema.yml": models__schema_yml,
        }

    @pytest.fixture(scope="class")
    def tests(self):
        return {
            "assert_positive_amounts.sql": tests__assert_positive_amounts_sql,
        }

    def test_column_renaming(self, project):
        """Verify columns are properly renamed in the staging model"""
        # Load seed data and run model
        run_dbt(["seed"])
        run_dbt(["run"])

        # Query the staging model to verify column names
        sql = "select * from {schema}.stg_orders limit 1".format(schema=project.test_schema)
        result = project.run_sql(sql, fetch="all")

        # Check that result has data
        assert len(result) > 0

        # The column names should be id, customer_id, order_date, status, amount
        # (order_id renamed to id, order_status renamed to status)

    def test_source_reference_works(self, project):
        """Verify that source() macro correctly references the seed table"""
        manifest = get_manifest(project.project_root)
        stg_orders_node = manifest.nodes.get("model.test.stg_orders")

        assert stg_orders_node is not None
        # Check that the model has a source dependency
        assert len(stg_orders_node.depends_on.nodes) > 0

        # Check that it references the raw_data.raw_orders source
        source_ref_exists = any(
            "source.test.raw_data.raw_orders" in dep for dep in stg_orders_node.depends_on.nodes
        )
        assert source_ref_exists, "Model should reference raw_data.raw_orders source"

    def test_materialization_is_view(self, project):
        """Verify model is materialized as a view"""
        # Run the model
        run_dbt(["seed"])
        run_dbt(["run"])

        # Check materialization
        created_objects = project.get_tables_in_schema()
        assert "stg_orders" in created_objects
        assert created_objects["stg_orders"] == "view", "stg_orders should be a view"

